#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumDeviation(vector<int>& nums) {
        priority_queue<int> pq;
        int min_val = 2e9;
        for (int x : nums) {
            if (x % 2 == 1) x *= 2;
            pq.push(x);
            min_val = min(min_val, x);
        }
        int min_dev = 2e9;
        while (true) {
            int max_val = pq.top(); pq.pop();
            min_dev = min(min_dev, max_val - min_val);
            if (max_val % 2 == 1) break;
            int half = max_val / 2;
            min_val = min(min_val, half);
            pq.push(half);
        }
        return min_dev;
    }
};

import java.util.*;

class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int minVal = Integer.MAX_VALUE;
        for (int x : nums) {
            if (x % 2 == 1) x *= 2;
            pq.offer(x);
            minVal = Math.min(minVal, x);
        }
        int minDev = Integer.MAX_VALUE;
        while (true) {
            int maxVal = pq.poll();
            minDev = Math.min(minDev, maxVal - minVal);
            if (maxVal % 2 == 1) break;
            int half = maxVal / 2;
            minVal = Math.min(minVal, half);
            pq.offer(half);
        }
        return minDev;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumDeviation = function(nums) {
    const pq = [];
    let minVal = Infinity;
    for (let x of nums) {
        if (x % 2 === 1) x *= 2;
        pq.push(x);
        if (x < minVal) minVal = x;
    }
    pq.sort((a, b) => b - a);
    let minDev = Infinity;
    while (true) {
        const maxVal = pq.shift();
        minDev = Math.min(minDev, maxVal - minVal);
        if (maxVal % 2 === 1) break;
        const half = Math.floor(maxVal / 2);
        if (half < minVal) minVal = half;
        // insert half in sorted order
        let lo = 0, hi = pq.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (pq[mid] > half) lo = mid + 1;
            else hi = mid;
        }
        pq.splice(lo, 0, half);
    }
    return minDev;
};
